UPDATE public.site_settings SET home_faqs = $j$[{"id":"hf1","answer":"AniRise operates globally, providing fully remote and on-call support for clients in Bangladesh and abroad.","question":"Where are you based?"},{"id":"hf2","answer":"A proposal is provided within 3–5 days after the initial call, and project kickoff occurs within 7 days of approval.","question":"How long does it take to start a project?"},{"id":"hf3","answer":"Both project-based and monthly retainer models are available. We provide quotes based on the scope after a free consultation.","question":"What is your pricing model?"},{"id":"hf4","answer":"You can expect to see early signals from SEO in 60–90 days, web/graphics deliverables within 2–4 weeks, and marketing campaigns within 2–3 weeks.","question":"When can I expect to see results?"},{"id":"hf5","answer":"Many projects often start with a simple Statement of Work (SOW). For long-term retainers, a standard service agreement is used.","question":"Is a contract required?"}]$j$::jsonb, service_faqs = $j${"website-seo":[{"id":"wseo1","answer":"Most clients see ranking improvements in 60–90 days, with significant traffic growth by month 4–6.","question":"How long until I see results?"},{"id":"wseo2","answer":"No reputable agency does. We guarantee a documented, ethical process and measurable progress.","question":"Do you guarantee #1 rankings?"},{"id":"wseo3","answer":"We combine technical depth with conversion-focused content — rankings without revenue is vanity.","question":"What makes AniRise different?"},{"id":"wseo4","answer":"Absolutely. We tailor scope to your stage and budget, from local SEO to enterprise campaigns.","question":"Do you work with small businesses?"}],"ecommerce-seo":[{"id":"eseo1","answer":"Yes — titles, descriptions, schema, internal linking, and category architecture.","question":"Do you optimize product pages?"},{"id":"eseo2","answer":"Shopify, WooCommerce, Magento, and custom builds.","question":"Which platforms do you support?"}],"graphics-design":[{"id":"gd1","answer":"Our standard package includes 3 rounds of revisions. Additional rounds are available for a small fee.","question":"How many rounds of revisions will I get?"},{"id":"gd2","answer":"Source files (AI/PSD/Figma) + print-ready PDF + web-ready PNG/JPG.","question":"What file formats will I receive?"}]}$j$::jsonb, case_studies = $j$[{"id":"cs1","link":"/portfolio","chart":{"data":[{"label":"M1","value":1200},{"label":"M2","value":1850},{"label":"M3","value":2400},{"label":"M4","value":3360}],"type":"line","title":"Monthly organic sessions"},"image":"/assets/portfolio-1-CaH0xDuC.jpg","intro":"For a local lifestyle brand, we ran a 90-day focused SEO sprint. Through technical clean-up, location-based keyword targeting, and content refreshing, organic visibility nearly tripled.","stats":[{"id":"s1","label":"Organic traffic","value":"+180%"},{"id":"s2","label":"Top-10 keywords","value":"68"},{"id":"s3","label":"Organic leads","value":"3.1x"},{"id":"s4","label":"Cost per lead","value":"-62%"}],"table":{"rows":[["Organic sessions / mo","1,200","3,360"],["Top-10 keywords","12","68"],["Avg. page speed (LCP)","4.2s","1.8s"],["Monthly organic leads","18","56"]],"title":"Before vs After (90 days)","headers":["Metric","Before","After"]},"title":"Local Brand SEO Sprint","client":"Lumen Lifestyle BD","metric":"+180% organic traffic","eyebrow":"Local SEO · 90 days","results":"Within 90 days, organic traffic increased by 180%, top-10 ranking keywords grew from 12 to 68, and organic leads nearly tripled. Cost-per-lead decreased by 62% compared to paid channels.","duration":"3 months","imageAlt":"Local brand SEO sprint dashboard","industry":"Retail · Lifestyle","solution":"We started with a technical audit — fixing Core Web Vitals, implementing schema markup, and refactoring site structure. Then, we created landing pages targeting 40+ high-intent local keywords, initiated a blog content cluster, and fully optimized their Google Business Profile.","challenge":"The brand was not visible in its local market. It didn't rank for keywords other than branded searches on Google, and its product pages were riddled with technical SEO issues — slow loading, duplicate meta descriptions, and weak internal linking.","description":"Within 3 months, organic traffic nearly tripled — driven by high-intent keyword targeting and on-page optimization."},{"id":"cs2","link":"/portfolio","chart":{"data":[{"label":"Q1","value":8},{"label":"Q2","value":14},{"label":"Q3","value":21},{"label":"Q4","value":25}],"type":"bar","title":"Quarterly organic revenue (BDT lakh)"},"image":"/assets/portfolio-2-CibwJ_8R.jpg","intro":"After restructuring the category architecture and product page SEO for a growing e-commerce brand, organic revenue more than tripled within 6 months.","stats":[{"id":"s1","label":"Organic revenue","value":"+212%"},{"id":"s2","label":"Qualified leads","value":"3.0x"},{"id":"s3","label":"Top-3 keywords","value":"47"},{"id":"s4","label":"Organic share","value":"46%"}],"table":{"rows":[["Organic sessions","9.4k","15.2k","24.8k","31.6k"],["Transactions","180","340","520","640"],["Avg order value","৳1,820","৳2,010","৳2,140","৳2,280"],["Top-3 keywords","4","18","33","47"]],"title":"Quarter-over-quarter performance","headers":["Metric","Q1","Q2","Q3","Q4"]},"title":"Ecommerce Revenue Lift","client":"NovaCart","metric":"3x leads · +212% revenue","eyebrow":"Ecommerce SEO · 6 months","results":"Organic revenue increased by 212%, top-3 rankings for transactional keywords grew from 4 to 47, and the organic share of total revenue increased from 18% to 46%.","duration":"6 months","imageAlt":"Ecommerce revenue lift case study","industry":"Ecommerce · Fashion","solution":"We implemented a full category restructure, product schema (Offer, Review, AggregateRating), faceted navigation fixes, and created 120+ optimized buying-intent landing pages. A content hub strategy was also launched.","challenge":"Category pages were filled with thin content, lacked product schema, and had weak internal linking. The result was a very low ability to rank for high-value keywords.","description":"Lead generation tripled with product schema and category restructuring."}]$j$::jsonb, updated_at = now() WHERE id = 1;